import{_ as n}from"./chunks/verwaltung-schule-vorschau.CVL_UyyH.js";import{_ as r,o as t,c as i,a3 as s}from"./chunks/framework.z_KJ15Ep.js";const f=JSON.parse('{"title":"Schuleinstellungen aufrufen","description":"","frontmatter":{"title":"Schuleinstellungen aufrufen","source_pageid":289,"source_revision":4406},"headers":[],"relativePath":"einstieg/erste-schritte/schule-verwaltung.md","filePath":"einstieg/erste-schritte/schule-verwaltung.md"}'),a={name:"einstieg/erste-schritte/schule-verwaltung.md"};function l(u,e,g,d,c,o){return t(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="schuleinstellungen-aufrufen" tabindex="-1">Schuleinstellungen aufrufen <a class="header-anchor" href="#schuleinstellungen-aufrufen" aria-label="Permalink to &quot;Schuleinstellungen aufrufen&quot;">​</a></h1><p>Unter Verwaltung → Schule finden Sie Schuldaten, organisatorische Angaben und den Wechsel in einen neuen Lernabschnitt.</p><p><a href="/bilder/erste-schritte/verwaltung-schule-vorschau.png"><img src="'+n+'" alt="Zusammenfassung der eingetragenen Schuldaten." loading="lazy"></a></p><p><em>Zusammenfassung der eingetragenen Schuldaten.</em></p><p>Unter dem Menüpunkt <em>Verwaltung</em> ➜ <strong>Schule</strong> sind die Programmpunkte zusammengefasst, die eher dem Aufgabenbereich der erweiterten Schulleitung oder der SchILD-NRW-Administration zugeschrieben werden können.</p><p>Die Unterpunkte von <em>Schule</em> sind</p><ul><li><strong>Vorschau</strong> wird direkt geöffnet und zeigt eine Zusammenfassung der Schuldaten.</li><li>Unter <strong>Allgemeine Angaben</strong> können die Grundeinstellungen zur Schule, wie die Anschrift und Einstellungen zur Gliederung oder andere organisatorische Angaben gemacht werden.</li><li>Über <strong>Weitere Angaben</strong> können Angaben zu Teilstandorten oder besondere Merkmale der Schule erfasst werden.</li><li><strong>Halbjahreswechsel</strong> ruft ein Fenster auf, mit dem der Übertrag in einen neuen Abschnitt vorgenommen werden kann.</li></ul><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Schule_(Verwaltung)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 4406.</p>',9)])])}const p=r(a,[["render",l]]);export{f as __pageData,p as default};
